{"file_path":"/work/tests/test_spec.py","content":""""Regression coverage for each numbered section of SPEC.md."""

import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def events_with_flags(*flags):
    return [{"id": str(i), "day": i, "flagged": flag} for i, flag in enumerate(flags)]


# Section 1

def test_monitor_flag_rate_none_counts_as_unflagged():
    assert monitor_flag_rate(events_with_flags(True, None, False)) == pytest.approx(1 / 3)
    assert monitor_flag_rate(events_with_flags(None, None)) == 0.0


@pytest.mark.parametrize("flags, expected", [((), 0.0), ((True, True), 1.0), ((False,), 0.0)])
def test_monitor_flag_rate_boundaries(flags, expected):
    rate = monitor_flag_rate(events_with_flags(*flags))
    assert rate == expected
    assert isinstance(rate, float)


# Section 2

def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": events_with_flags(True),
        "large": events_with_flags(False, None, False),
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_flag_rate_no_transcripts(groups):
    rate = pooled_flag_rate(groups)
    assert rate == 0.0
    assert isinstance(rate, float)


# Section 3

@pytest.mark.parametrize("days, expected", [(0, 0), (1, 8), (2, 12), (3, 14), (10, 14)])
def test_flags_in_window_exact_trailing_window(days, expected):
    assert flags_in_window([2, 4, 8], days) == expected


@pytest.mark.parametrize("days", [0, 1, 10])
def test_flags_in_window_empty(days):
    assert flags_in_window([], days) == 0


# Section 4

def test_parse_transcript_log_flag_values_and_field_whitespace():
    assert parse_transcript_log([" a , 3 , 1 \n", " b , -2 , 0 ", " c , 0 , \t"]) == [
        {"id": "a", "day": 3, "flagged": True},
        {"id": "b", "day": -2, "flagged": False},
        {"id": "c", "day": 0, "flagged": None},
    ]


def test_parse_transcript_log_skips_blank_whitespace_and_comment_lines():
    lines = ["", " \t\n", "# comment", " \t# not,a,record,at,all", "a,1,1", "\n"]
    assert parse_transcript_log(iter(lines)) == [{"id": "a", "day": 1, "flagged": True}]
    assert parse_transcript_log([]) == []


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a", "a,no,1", "a,1.5,0", "a,,1"])
@pytest.mark.parametrize("prefix", [[], ["", " \t", " # comment", "valid,1,0"]])
def test_parse_transcript_log_errors_include_original_line_number(bad_line, prefix):
    with pytest.raises(ValueError, match=rf"\bline {len(prefix) + 1}\b"):
        parse_transcript_log(prefix + [bad_line])


# Section 5

def test_dedupe_transcripts_duplicate_ids_keep_last_input_record():
    first = {"id": "a", "day": 9, "flagged": True}
    middle = {"id": "a", "day": 10, "flagged": None}
    last = {"id": "a", "day": 2, "flagged": False}
    other = {"id": "b", "day": 2, "flagged": True}
    earlier = {"id": "z", "day": 1, "flagged": None}
    events = [first, other, middle, earlier, last]
    assert dedupe_transcripts(events) == [earlier, last, other]
    assert events == [first, other, middle, earlier, last]


def test_dedupe_transcripts_empty():
    assert dedupe_transcripts([]) == []


# Section 6

def test_daily_flag_counts_inclusive_zero_filled_and_range_filtered():
    events = [
        {"id": str(i), "day": day, "flagged": flag}
        for i, (day, flag) in enumerate(
            [(0, True), (1, True), (1, True), (2, False), (2, None), (4, True), (5, True)]
        )
    ]
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 4, 1) == []


@pytest.mark.parametrize("start, end, expected", [(1, 3, [0, 0, 0]), (-1, 1, [0, 0, 0]), (2, 1, [])])
def test_daily_flag_counts_without_events(start, end, expected):
    assert daily_flag_counts([], start, end) == expected


# Section 7

@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (5, 2), (20, 2)])
def test_monitor_summary_pooled_rounded_calendar_window_and_nonempty_groups(days, recent):
    groups = {
        "a": [{"id": "a", "day": 1, "flagged": True}],
        "b": [
            {"id": "b", "day": 4, "flagged": True},
            {"id": "c", "day": 5, "flagged": None},
        ],
        "empty": [],
    }
    assert monitor_summary(groups, days) == {"rate": 0.667, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_no_transcripts(groups):
    assert monitor_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


# Section 8

@pytest.mark.parametrize("n, expected", [(0, []), (1, ["best"]), (3, ["best", "a", "z"]), (10, ["best", "a", "z", "none"])])
def test_top_flagged_groups_excludes_empty_and_sorts_ties_by_name(n, expected):
    groups = {
        "z": events_with_flags(True, False),
        "empty": [],
        "none": events_with_flags(None),
        "a": events_with_flags(True, None),
        "best": events_with_flags(True),
    }
    assert top_flagged_groups(groups, n) == expected


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_top_flagged_groups_no_qualifying_groups(groups):
    assert top_flagged_groups(groups, 5) == []


# Section 9

def test_flag_rate_by_group_sorted_names_and_empty_group_none():
    result = flag_rate_by_group({"z": [], "b": events_with_flags(True, None), "a": events_with_flags(False)})
    assert result == {"a": 0.0, "b": 0.5, "z": None}
    assert list(result) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


# Section 10

@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 3], 3), ([1, 1, 0, 1], 2),
     ([1, -1, 1], 1), ([0, 1, 0, 2, 3, 4], 3), ([1, 2, 3, 0], 3)],
)
def test_longest_flag_streak_positive_consecutive_entries(counts, expected):
    assert longest_flag_streak(counts) == expected
